"use client";
import { ShaderSurface, type ShaderSurfaceOptions } from "./shader-surface";
export interface MeshGradientProps
  extends Pick<
    ShaderSurfaceOptions,
    | "children"
    | "className"
    | "style"
    | "height"
    | "colors"
    | "speed"
    | "scale"
    | "intensity"
    | "mouseStrength"
    | "maxDpr"
    | "onReady"
  > {}
/** Moving color fields with pointer displacement and a static CSS fallback. */
export function MeshGradient(props: MeshGradientProps) {
  return <ShaderSurface kind="mesh" scale={1} speed={1} {...props} />;
}
